import re

SAMPLE = {"repo": "pallets/click"}


def main(input_data):
    d = input_data if isinstance(input_data, dict) and input_data.get("repo") else SAMPLE
    repo = str(d["repo"]).strip().removeprefix("https://github.com/").strip("/")
    if not re.fullmatch(r"[\w.-]+/[\w.-]+", repo):
        raise ValueError("Use the form owner/name, for example pallets/click")
    return {"repo": repo}

from datetime import datetime


def main(input_data):
    repo = input_data["compose"]["repo"]
    stamp = datetime.now().astimezone().strftime("%Y-%m-%d %H:%M")
    return {"text": "## %s (%s)\n\n%s\n\nSee the map: paste https://github.com/%s into the Explorer.\n\n---\n\n"
            % (repo, stamp, input_data["explain"]["text"].strip(), repo)}
